                        "REQUESTID, TRANSACTIONID, AMOUNTLINKEDINBPM, AMOUNTINCURRENTREQ,AMOUNTINREQCURRENCY, ISDELETED) " +    
                        "VALUES (?, ?, ?, ?, ?,?)";
    
    tw.local.sqlStatement.parameters.insertIntoList(tw.local.sqlStatement.parameters.listLength, addSQLParameter(tw.local.data.requestID));
    tw.local.sqlStatement.parameters.insertIntoList(tw.local.sqlStatement.parameters.listLength, addSQLParameter(tw.local.transactionID));
